/**
 * Bundled example datasets ("Use sample dataset", PLAN §2.2 privacy: public demos use only
 * synthetic or licensed data with clearly labelled provenance).
 *
 * Shipped: every synthetic fixture that has data (generated by this repository, labelled
 * SYNTHETIC) and ACSI 2015 (CC BY 4.0, with the attribution required by
 * packages/fixtures/third-party/smartpls-samples/PROVENANCE.md).
 * NOT shipped: tam, utaut, oi, concise-guide, hbat — their redistribution terms are
 * unverified and their CSVs are git-ignored.
 *
 * The CSV texts are lazy `?raw` imports: each becomes its own chunk, fetched only when a
 * sample is opened, so the registry below costs a few hundred bytes in the main bundle.
 * bundled.test.ts checks this registry against the fixture manifests.
 */
import type { DatasetRef } from '@sem-studio/contracts';
import { createDataset } from './transform';
import type { Dataset } from './types';

export const SYNTHETIC_STATEMENT =
  'SYNTHETIC benchmark/teaching data generated by SEM Studio from a stated population model; it represents no real study.';

export const ACSI_ATTRIBUTION =
  'Hult, Tomas; Morgeson, Forrest (2023), "The American Customer Satisfaction Index (ACSI): A Sample Dataset and Description", Mendeley Data, V2, doi: 10.17632/64xkbj2ry5.2. Licensed under CC BY 4.0. Changes made: converted to CSV; the missing-data codes 98 and 99, SPSS \'#NULL!\' cells and empty cells are written as empty fields.';

export const CC_BY_4_URL = 'https://creativecommons.org/licenses/by/4.0/';

export interface BundledDatasetInfo {
  /** stable example id, stored in Dataset.source.exampleId */
  id: string;
  title: string;
  rows: number;
  columns: number;
  synthetic: boolean;
  /** shown next to the dataset wherever it is offered or used */
  provenance: NonNullable<DatasetRef['provenance']>;
  licenceUrl?: string;
}

const synthetic = (
  id: string,
  title: string,
  rows: number,
  columns: number,
): BundledDatasetInfo => ({
  id,
  title: `${title} (SYNTHETIC)`,
  rows,
  columns,
  synthetic: true,
  provenance: { synthetic: true, attribution: SYNTHETIC_STATEMENT },
});

export const BUNDLED_DATASETS: readonly BundledDatasetInfo[] = [
  synthetic('pls-two-construct', 'Two reflective constructs, 7-point Likert', 300, 7),
  synthetic(
    'pls-mixed-composite',
    'Composite (Mode B) plus reflective constructs, 7-point Likert',
    400,
    11,
  ),
  synthetic('tam-mediation', 'TAM mediation (PEOU -> PU -> BI), 7-point Likert', 500, 11),
  synthetic('ipma-range-restricted', 'IPMA with range-restricted items (scale 1..7)', 400, 11),
  synthetic('poor-discriminant', 'Known poor discriminant validity (corr(A,B) = .95)', 400, 11),
  synthetic('cfa-one-factor', 'One-factor CFA, continuous', 500, 5),
  synthetic('cfa-two-factor', 'Two-factor CFA, continuous', 500, 8),
  synthetic('cfa-two-factor-ordinal', 'Two-factor CFA, 5-point ordinal', 600, 8),
  synthetic('missing-mcar', 'Two-factor CFA with 8% MCAR missingness', 500, 8),
  synthetic('tam-mediation-exact', 'TAM mediation, exact covariance (analytic oracle)', 500, 11),
  synthetic('cfa-two-factor-exact', 'Two-factor CFA, exact covariance (analytic oracle)', 500, 8),
  synthetic(
    'pls-mixed-composite-exact',
    'Composite plus reflective, exact covariance (analytic oracle)',
    400,
    11,
  ),
  synthetic(
    'cb-heywood-exact',
    'Heywood case (negative residual variance), exact correlations',
    200,
    3,
  ),
  synthetic('cb-singular', 'Singular covariance (s7 = s1 + s2)', 300, 7),
  synthetic('delone-mclean', 'IS success model inspired by DeLone & McLean (SYNTHETIC)', 400, 23),
  synthetic('service-quality', 'Service quality -> satisfaction -> loyalty (SYNTHETIC)', 450, 13),
  synthetic(
    'acsi-inspired',
    'Customer satisfaction model inspired by the ACSI (SYNTHETIC)',
    500,
    14,
  ),
  synthetic('utaut2-inspired', 'Technology adoption model inspired by UTAUT2 (SYNTHETIC)', 450, 27),
  synthetic('item-screening', 'Item screening: a reverse-worded and a constant item', 300, 8),
  {
    id: 'acsi-2015',
    title: 'American Customer Satisfaction Index (ACSI) 2015 sample data',
    rows: 8239,
    columns: 29,
    synthetic: false,
    provenance: { synthetic: false, licence: 'CC BY 4.0', attribution: ACSI_ATTRIBUTION },
    licenceUrl: CC_BY_4_URL,
  },
];

const SYNTHETIC_PREFIX = '../../../../../packages/fixtures/synthetic/';

// Lazy: one chunk per file, loaded on demand. The pattern covers synthetic fixtures only.
const syntheticCsv = import.meta.glob<string>(
  '../../../../../packages/fixtures/synthetic/*/data.csv',
  {
    query: '?raw',
    import: 'default',
  },
);

function loader(id: string): (() => Promise<string>) | undefined {
  if (id === 'acsi-2015') {
    return () =>
      import('../../../../../packages/fixtures/third-party/smartpls-samples/acsi-2015/data.csv?raw').then(
        (m) => m.default,
      );
  }
  return syntheticCsv[`${SYNTHETIC_PREFIX}${id}/data.csv`];
}

export function bundledDatasetInfo(id: string): BundledDatasetInfo | undefined {
  return BUNDLED_DATASETS.find((d) => d.id === id);
}

/** Raw CSV text of a bundled example. Throws for an unknown id. */
export async function loadBundledCsv(id: string): Promise<string> {
  const load = bundledDatasetInfo(id) ? loader(id) : undefined;
  if (!load) throw new Error(`Unknown bundled dataset "${id}".`);
  return load();
}

/** A bundled example as a Dataset (source.kind = 'bundled'). */
export async function loadBundledDataset(
  id: string,
  options: { datasetId?: string; importedAt?: string } = {},
): Promise<Dataset> {
  const info = bundledDatasetInfo(id);
  if (!info) throw new Error(`Unknown bundled dataset "${id}".`);
  const text = await loadBundledCsv(id);
  const result = await createDataset(text, {
    name: info.title,
    source: { kind: 'bundled', exampleId: id },
    ...(options.datasetId !== undefined ? { id: options.datasetId } : {}),
    ...(options.importedAt !== undefined ? { importedAt: options.importedAt } : {}),
  });
  if ('error' in result)
    throw new Error(`Bundled dataset "${id}" failed to load: ${result.error.code}.`);
  return result;
}
